import{_ as r,o as d,c as o,a2 as s}from"./chunks/framework.CRFziyHp.js";const n="/images/placeholder-architecture.svg",u=JSON.parse('{"title":"区域管理","description":"","frontmatter":{},"headers":[],"relativePath":"config/region.md","filePath":"config/region.md","lastUpdated":1785013113000}'),a={name:"config/region.md"};function e(g,t,i,h,l,c){return d(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="区域管理" tabindex="-1">区域管理 <a class="header-anchor" href="#区域管理" aria-label="Permalink to &quot;区域管理&quot;">​</a></h1><p>灵萌支持<strong>多区域</strong>（多校区、多社区）独立运营。本文说明 <strong>区域列表</strong> 各字段与 <strong>系统级区域模式</strong> 对用户端（C 端）的影响；用户注册登录、资料、签到等规则见 <a href="/config/user-rules">用户规则</a>。</p><hr><h2 id="一、区域列表" tabindex="-1">一、区域列表 <a class="header-anchor" href="#一、区域列表" aria-label="Permalink to &quot;一、区域列表&quot;">​</a></h2><p>路径：<strong>区域管理 → 区域列表</strong></p><p><img src="'+n+'" alt="区域列表"></p><h3 id="常用操作" tabindex="-1">常用操作 <a class="header-anchor" href="#常用操作" aria-label="Permalink to &quot;常用操作&quot;">​</a></h3><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td>新建区域</td><td>填写名称、类型、地址、坐标等</td></tr><tr><td>编辑</td><td>修改区域信息与开关</td></tr><tr><td>启用 / 禁用</td><td>控制区域是否对 C 端可见、可选</td></tr><tr><td>负责人</td><td>设置主负责人与子负责人</td></tr></tbody></table><h3 id="基础信息字段-→-c-端影响" tabindex="-1">基础信息字段 → C 端影响 <a class="header-anchor" href="#基础信息字段-→-c-端影响" aria-label="Permalink to &quot;基础信息字段 → C 端影响&quot;">​</a></h3><table tabindex="0"><thead><tr><th>后台字段</th><th>C 端表现</th><th>验收要点</th></tr></thead><tbody><tr><td><strong>区域名称</strong></td><td>区域选择页、切换区域、部分内容卡片上显示的名称</td><td>改名后 C 端列表同步更新</td></tr><tr><td><strong>区域类型</strong></td><td>校园 / 社区 / 其他；用于区域页筛选 Tab</td><td>筛选「校园」仅显示 campus 类型</td></tr><tr><td><strong>地址</strong></td><td>区域详情/列表辅助展示</td><td>—</td></tr><tr><td><strong>Logo</strong></td><td>区域选择卡片左侧图标；无 Logo 时显示名称首字</td><td>上传后 C 端可见</td></tr><tr><td><strong>背景图</strong></td><td>区域相关展示位（若有）</td><td>—</td></tr><tr><td><strong>相册</strong></td><td>区域介绍类页面轮播（若前端有接入）</td><td>—</td></tr><tr><td><strong>负责人</strong></td><td>后台管理用；C 端一般不直接展示负责人表单字段</td><td>—</td></tr></tbody></table><h3 id="位置信息-→-c-端影响" tabindex="-1">位置信息 → C 端影响 <a class="header-anchor" href="#位置信息-→-c-端影响" aria-label="Permalink to &quot;位置信息 → C 端影响&quot;">​</a></h3><table tabindex="0"><thead><tr><th>后台字段</th><th>取值</th><th>C 端表现</th></tr></thead><tbody><tr><td><strong>纬度 / 经度</strong></td><td>有效坐标</td><td>区域选择页可计算「距你 XXX m/km」；配合距离限制过滤</td></tr><tr><td><strong>纬度 / 经度</strong></td><td>0 或未填</td><td>距离标签显示「距你 --」；<strong>不参与</strong>按距离过滤</td></tr><tr><td><strong>距离限制（米）</strong></td><td>0</td><td><strong>不限距离</strong>，列表显示所有已启用区域（仍受系统级距离策略约束，见下文）</td></tr><tr><td><strong>距离限制（米）</strong></td><td>N（如 1000）</td><td>单区域维度的距离参考；与系统 <strong>区域配置 Tab</strong> 的全局距离限制叠加使用时，以 C 端区域页逻辑为准：用户定位可用时，超出限制的区域可能不出现在可选列表</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>运营上建议：每个对外开放的校区都填好坐标，否则用户看不到距离，也无法按距离筛选。</p></div><h3 id="开关选项-→-c-端影响" tabindex="-1">开关选项 → C 端影响 <a class="header-anchor" href="#开关选项-→-c-端影响" aria-label="Permalink to &quot;开关选项 → C 端影响&quot;">​</a></h3><table tabindex="0"><thead><tr><th>后台字段</th><th>开启</th><th>关闭</th><th>C 端表现</th></tr></thead><tbody><tr><td><strong>热门</strong></td><td>是</td><td>否</td><td>区域选择页「热门」筛选下展示；列表排序热门优先</td></tr><tr><td><strong>区域私信</strong></td><td>开启</td><td>关闭</td><td><strong>开启</strong>：用户可正常使用私信、群聊（仍受笔记/消息等业务规则约束）<br><strong>关闭</strong>：普通用户私信/群聊入口隐藏或不可用；<strong>仅保留与官方机器人账号的私聊</strong></td></tr><tr><td><strong>允许提现</strong></td><td>开启</td><td>关闭</td><td>与全站提现总开关 <strong>同时</strong> 为开时，该区域用户才可发起提现</td></tr><tr><td><strong>提现手续费 / 费率</strong></td><td>数值</td><td>—</td><td>该区域用户提现时按配置计费（C 端提现页展示金额会体现规则）</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">区域私信 vs 全站</p><p>未绑定区域的用户，是否可私信由 <strong>系统配置</strong> 中的「无区域用户私信」类开关决定（见 <a href="/config/system-settings">系统配置</a>）。<br> 已绑定区域的用户，以 <strong>区域列表 → 区域私信</strong> 为准。</p></div><h3 id="启用-禁用-status" tabindex="-1">启用 / 禁用（status） <a class="header-anchor" href="#启用-禁用-status" aria-label="Permalink to &quot;启用 / 禁用（status）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>状态</th><th>C 端表现</th></tr></thead><tbody><tr><td><strong>启用</strong></td><td>区域出现在 C 端区域列表（<code>status=1</code> 查询）；用户可选、可绑定</td></tr><tr><td><strong>禁用</strong></td><td>C 端区域列表<strong>不展示</strong>该区域；已绑定该区的老用户行为取决于业务（内容仍可能带历史 region_id，但新区不可选）</td></tr></tbody></table><p><strong>验收</strong>：禁用某区域后，打开 C 端区域选择页，该区域应消失。</p><h3 id="平台默认-region-id-0" tabindex="-1">平台默认（region_id = 0） <a class="header-anchor" href="#平台默认-region-id-0" aria-label="Permalink to &quot;平台默认（region_id = 0）&quot;">​</a></h3><ul><li>在 <strong>用户配置</strong> 等页面中，<strong>平台默认</strong> 表示全站兜底规则，不是一条真实「校区」记录</li><li>未单独配置的子区域，其 <strong>用户规则</strong> 继承平台默认；详见 <a href="/config/user-rules#操作入口与配置继承">用户规则 → 配置继承</a></li></ul><hr><h2 id="二、系统级区域模式" tabindex="-1">二、系统级区域模式 <a class="header-anchor" href="#二、系统级区域模式" aria-label="Permalink to &quot;二、系统级区域模式&quot;">​</a></h2><p>路径：<strong>系统设置 → 系统配置 → 区域配置 Tab</strong></p><p>与区域列表配合：<strong>此处定「用户怎么进区域」</strong>，区域列表定 <strong>「有哪些区域」</strong>。</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><strong>区域模式</strong></td><td>见下表</td></tr><tr><td><strong>固定区域</strong></td><td>模式为「固定区域」时，选择具体区域，不能选 0</td></tr><tr><td><strong>距离限制（米）</strong></td><td>全站默认距离过滤半径，默认 1000；用户授权定位后，区域选择页可能隐藏超出该距离的区域</td></tr></tbody></table><h3 id="三种模式-→-c-端表现" tabindex="-1">三种模式 → C 端表现 <a class="header-anchor" href="#三种模式-→-c-端表现" aria-label="Permalink to &quot;三种模式 → C 端表现&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模式</th><th>后台配置</th><th>C 端表现</th></tr></thead><tbody><tr><td><strong>平台模式</strong>（全站单区）</td><td><code>single_region_id = 0</code></td><td>用户<strong>无需</strong>选区域；新用户不强制绑定具体校区；跳过区域选择页</td></tr><tr><td><strong>多区域自选</strong></td><td>不设置固定 ID（null）</td><td>注册或首次进入时需进入 <strong>区域选择页</strong> 挑选校区/社区；选完后写入本地与账号</td></tr><tr><td><strong>固定区域</strong></td><td>指定某一区域 ID</td><td>新用户<strong>自动绑定</strong>该区域；<strong>跳过</strong>区域选择页</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">已绑定用户</p><p>用户账号 <strong>已有 region_id</strong> 时，一般<strong>不允许</strong>再到区域页随意切换（防止跨区运营混乱）。换区通常需后台改用户所属区域或走专门业务流程。</p></div><h3 id="距离限制如何作用在-c-端" tabindex="-1">距离限制如何作用在 C 端 <a class="header-anchor" href="#距离限制如何作用在-c-端" aria-label="Permalink to &quot;距离限制如何作用在 C 端&quot;">​</a></h3><ol><li>用户打开 <strong>区域选择页</strong> 并授权定位</li><li>读取系统 <strong>区域配置 Tab</strong> 的「距离限制（米）」</li><li>对每个 <strong>已启用</strong> 且 <strong>有坐标</strong> 的区域计算球面距离</li><li>超出限制的区域 <strong>不出现在可选列表</strong>（热门筛选同样受约束）</li></ol><p><strong>验收 checklist</strong></p><ul><li>[ ] 三种区域模式各测一遍：是否出现区域页、新用户 region 是否正确</li><li>[ ] 距离限制设为 500m：远端校区在列表中消失</li><li>[ ] 关闭定位权限：列表应仍展示区域，但距离显示「距你 --」</li></ul><hr><h2 id="三、各业务「区域-××-配置」" tabindex="-1">三、各业务「区域 ×× 配置」 <a class="header-anchor" href="#三、各业务「区域-××-配置」" aria-label="Permalink to &quot;三、各业务「区域 ×× 配置」&quot;">​</a></h2><p>在 <strong>区域管理</strong> 菜单下，除 <strong>用户配置</strong> 外还有按业务的区域配置页。每个页面顶部的 <strong>「启用」</strong> 一般表示：<strong>关闭后，该区域 C 端用户看不到或不生效对应功能模块</strong>（具体以各模块文档为准）。</p><table tabindex="0"><thead><tr><th>菜单</th><th>作用</th><th>C 端关联</th></tr></thead><tbody><tr><td><strong><a href="/config/user-rules">用户配置</a></strong></td><td>注册登录、资料、认证、签到</td><td>登录注册、资料页、引导页、签到页</td></tr><tr><td><strong>笔记配置</strong></td><td>发帖、评论、审核、浏览量</td><td>发帖、圈子笔记流</td></tr><tr><td><strong>话题配置</strong></td><td>话题模块</td><td>话题广场、话题详情</td></tr><tr><td><strong>投票配置</strong></td><td>投票活动</td><td>投票参与页</td></tr><tr><td><strong>评选活动配置</strong></td><td>评选模块</td><td>评选活动页</td></tr><tr><td><strong>闲置配置</strong></td><td>二手闲置</td><td>闲置发布与交易</td></tr><tr><td><strong>评分配置</strong></td><td>区域评分</td><td>评分相关页</td></tr><tr><td><strong>等级特权</strong></td><td>用户等级权益</td><td>等级特权展示与领取</td></tr><tr><td><strong>笔记热度 / 热帖精帖</strong></td><td>内容排序</td><td>首页/圈子排序结果</td></tr></tbody></table><p><strong>推荐配置顺序</strong></p><ol><li><a href="/config/system-settings#tab-9区域配置">系统配置 → 区域配置</a> 选定模式与全站距离</li><li><strong>区域列表</strong> 创建并 <strong>启用</strong> 具体区域，填坐标与 Logo</li><li><strong><a href="/config/user-rules">用户配置</a></strong> 打开 <strong>启用</strong>，设置注册登录与门禁</li><li>按需打开笔记、话题等业务区域配置</li></ol><hr><h2 id="四、区域管理与用户规则对照" tabindex="-1">四、区域管理与用户规则对照 <a class="header-anchor" href="#四、区域管理与用户规则对照" aria-label="Permalink to &quot;四、区域管理与用户规则对照&quot;">​</a></h2><p>运营常把两类配置混在一起，可按下表区分：</p><table tabindex="0"><thead><tr><th>需求</th><th>改哪里</th></tr></thead><tbody><tr><td>关闭某校区注册 / 微信登录</td><td><a href="/config/user-rules">用户配置</a></td></tr><tr><td>强制学生认证才能发帖</td><td><a href="/config/user-rules">用户配置</a></td></tr><tr><td>某校区不在列表展示</td><td><strong>区域列表 → 禁用</strong></td></tr><tr><td>某校区用户不能互相私信</td><td><strong>区域列表 → 区域私信 → 关闭</strong></td></tr><tr><td>用户必须先选校区</td><td><strong>系统配置 → 多区域自选</strong> + <a href="/config/user-rules">用户配置</a>「注册时必须选择区域」</td></tr><tr><td>全站只有一个虚拟区域</td><td><strong>系统配置 → 平台模式</strong></td></tr><tr><td>新用户全部进「XX 大学」</td><td><strong>系统配置 → 固定区域</strong> 选该校</td></tr></tbody></table><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/config/user-rules">用户规则</a> — 每个用户开关的 C 端影响（本文姊妹篇）</li><li><a href="/config/system-settings">系统配置</a> — 区域模式、距离限制、新用户信息模式</li><li><a href="/features/circle-note">圈子与笔记</a></li></ul>',46)])])}const f=r(a,[["render",e]]);export{u as __pageData,f as default};
